def get_all_elements(root1, root2):
    def spine(node, stack):
        while node:
            stack.append(node)
            node = node.left

    s1, s2, out = [], [], []
    spine(root1, s1)
    spine(root2, s2)
    while s1 or s2:
        if not s2 or (s1 and s1[-1].val <= s2[-1].val):
            node = s1.pop(); spine(node.right, s1)
        else:
            node = s2.pop(); spine(node.right, s2)
        out.append(node.val)
    return out
